	@Test
	public void nestedSelectStarV3() {
		final String query = " SELECT col1 FROM "
			+	"\n (select * from " 
			+   "\n  (select col1, col2 from third) as T3 where T3.col3 is null) F4";

		final SQLSelectParserParser parser = parse(query);
		SqlParseEventWalker extractor = runParsertest(query, parser);
		assertNoFatalErrors(extractor);
		assertNoWalkerDiagnostics(extractor);
		
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=null}}}, from={table={alias=F4, query={select={1={column={name=*, table_ref=*}}}, from={table={alias=T3, query={select={1={column={name=col1, table_ref=null}}, 2={column={name=col2, table_ref=null}}}, from={table={alias=null, table=third}}}}}, where={condition={left={column={name=col3, table_ref=T3}}, operator=is null}}}}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[col1]", 
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{third={col2=[[@11,52:55='col2',<392>,3:16]], col1=[[@9,46:49='col1',<392>,3:10]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", 
		"{query0={*=[[@5,28:28='*',<291>,2:9]], col2=[[@11,52:55='col2',<392>,3:16]], col3=[[@18,81:82='T3',<392>,3:45]], col1=[[@9,46:49='col1',<392>,3:10]]}, query1={*=[[@5,28:28='*',<291>,2:9]], col1=[[@1,8:11='col1',<392>,1:8]]}, query2={col1=[[@1,8:11='col1',<392>,1:8]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong",
		 "{def_query2={query_dictionary={col1=[[@1,8:11='col1',<392>,1:8]]}, def_query1={query_dictionary={*=[[@5,28:28='*',<291>,2:9]], col1=[[@1,8:11='col1',<392>,1:8]]}, def_query0={query_dictionary={*=[[@5,28:28='*',<291>,2:9]], col2=[[@11,52:55='col2',<392>,3:16]], col3=[[@18,81:82='T3',<392>,3:45]], col1=[[@9,46:49='col1',<392>,3:10]]}, table_dictionary={third={col2=[[@11,52:55='col2',<392>,3:16]], col1=[[@9,46:49='col1',<392>,3:10]]}}, interface={col2=[{name=col2, table_ref=third}], col1=[{name=col1, table_ref=third}]}}, filters=[{name=col3, table_ref=T3}], interface={*=[{name=*, table_ref=*}]}, table_alias={T3=query0}}, interface={col1=[{name=col1, table_ref=query1}]}, table_alias={F4=query1}}}",
				extractor.getSymbolTable().toString());
	}

	@Test
	public void nestedSelectStarV4() {
		final String query = " SELECT F4.col1 FROM "
			+	"\n (select * from " 
			+   "\n  (select col1, col2 from third) as T3) F4";

		final SQLSelectParserParser parser = parse(query);
		SqlParseEventWalker extractor = runParsertest(query, parser);
		assertNoFatalErrors(extractor);
		assertNoWalkerDiagnostics(extractor);
		
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=F4}}}, from={table={alias=F4, query={select={1={column={name=*, table_ref=*}}}, from={table={alias=T3, query={select={1={column={name=col1, table_ref=null}}, 2={column={name=col2, table_ref=null}}}, from={table={alias=null, table=third}}}}}}}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[col1]", 
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{third={col2=[[@13,55:58='col2',<392>,3:16]], col1=[[@11,49:52='col1',<392>,3:10]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", 
		"{query0={col2=[[@13,55:58='col2',<392>,3:16]], *=[[@7,31:31='*',<291>,2:9]], col1=[[@11,49:52='col1',<392>,3:10]]}, query1={*=[[@7,31:31='*',<291>,2:9]], col1=[[@1,8:9='F4',<392>,1:8]]}, query2={col1=[[@3,11:14='col1',<392>,1:11]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong", 
		"{def_query2={query_dictionary={col1=[[@3,11:14='col1',<392>,1:11]]}, def_query1={query_dictionary={*=[[@7,31:31='*',<291>,2:9]], col1=[[@1,8:9='F4',<392>,1:8]]}, def_query0={query_dictionary={*=[[@7,31:31='*',<291>,2:9]], col2=[[@13,55:58='col2',<392>,3:16]], col1=[[@11,49:52='col1',<392>,3:10]]}, table_dictionary={third={col2=[[@13,55:58='col2',<392>,3:16]], col1=[[@11,49:52='col1',<392>,3:10]]}}, interface={col2=[{name=col2, table_ref=third}], col1=[{name=col1, table_ref=third}]}}, interface={*=[{name=*, table_ref=*}]}, table_alias={T3=query0}}, interface={col1=[{name=col1, table_ref=F4}]}, table_alias={F4=query1}}}",
				extractor.getSymbolTable().toString());
	}


	@Test
	public void nestedSelectStarV5() {
		final String query = " SELECT T3.col1 FROM "
			+	"\n (select * from " 
			+   "\n  (select * from third) as T3) F4";

		final SQLSelectParserParser parser = parse(query);
		SqlParseEventWalker extractor = runParsertest(query, parser);
		
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=T3}}}, from={table={alias=F4, query={select={1={column={name=*, table_ref=*}}}, from={table={alias=T3, query={select={1={column={name=*, table_ref=*}}}, from={table={alias=null, table=third}}}}}}}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[col1]", 
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{third={*=[[@11,49:49='*',<291>,3:10]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{query0={*=[[@11,49:49='*',<291>,3:10]]}, query1={*=[[@7,31:31='*',<291>,2:9]]}, query2={col1=[[@3,11:14='col1',<392>,1:11]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong", "{def_query2={query_dictionary={col1=[[@3,11:14='col1',<392>,1:11]]}, table_dictionary={}, def_query1={query_dictionary={*=[[@7,31:31='*',<291>,2:9]]}, def_query0={query_dictionary={*=[[@11,49:49='*',<291>,3:10]]}, table_dictionary={third={*=[[@11,49:49='*',<291>,3:10]]}}, interface={*=[{name=*, table_ref=*}]}}, interface={*=[{name=*, table_ref=*}]}, table_alias={T3=query0}}, interface={col1=[{name=col1, table_ref=T3}]}, table_alias={F4=query1}}}",
				extractor.getSymbolTable().toString());

		Snippet snippet = extractor.getSnippet();
		assertFatalDiagnosticAtPosition(snippet, "QUALIFIED_COLUMN_NOT_FOUND_IN_TABLE",
				"Source Table not found for Column 'col1' at (l:1 c:11). No alias or table called 'T3'.",
				"col1", 1, 11);
		assertFatalDiagnosticCount(snippet, "QUALIFIED_COLUMN_NOT_FOUND_IN_TABLE", "Source Table not found for Column 'col1'", "col1", 1);
	}


