		assertDiagnosticCountBySeverity(
				snippet,
				"UNRESOLVED_UNQUALIFIED_COLUMNS",
				ParseDiagnostic.Severity.ERROR,
				null,
				"missing",
				1);
		assertDiagnosticCountBySeverity(
				snippet,
				"AMBIGUOUS_COLUMN_REFERENCE",
				ParseDiagnostic.Severity.SEVERE_WARNING,
				null,
				"missing",
				1);
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=F4}, alias=last}, 2={column={name=col2, table_ref=t}, alias=tcol2}, 3={column={name=col3, table_ref=t}}}, from={join={1={table={alias=F4, query={select={1={column={name=a, table_ref=null}, alias=col1}, 2={column={name=b, table_ref=null}, alias=col4}, 3={column={name=col6, table_ref=null}}, 4={column={name=col8, table_ref=null}}, 5={column={name=col9, table_ref=null}}}, from={table={alias=null, table=third}}}}}, 2={join=join, on={and={1={condition={left={column={name=col1, table_ref=F4}}, right={column={name=col2, table_ref=t}}, operator==}}, 2={condition={left={column={name=col4, table_ref=F4}}, right={column={name=col5, table_ref=t}}, operator==}}}}}, 3={table={alias=t, table=fourth}}, 4={join=join, on={condition={left={column={name=col1, table_ref=F4}}, right={column={name=col2, table_ref=f}}, operator==}}}, 5={table={alias=f, table=fifth}}}}, where={and={1={condition={left={column={name=col6, table_ref=F4}}, right={column={name=col7, table_ref=t}}, operator==}}, 2={condition={left={column={name=col1, table_ref=F4}}, right={column={name=col2, table_ref=t}}, operator==}}, 3={condition={left={column={name=col8, table_ref=F4}}, right={literal=0}, operator=>}}}}, qualify={and={1={condition={left={column={name=col9, table_ref=F4}}, right={column={name=col10, table_ref=t}}, operator==}}, 2={condition={left={column={name=col8, table_ref=F4}}, right={literal=1}, operator=>}}, 3={condition={left={column={name=missing, table_ref=null}}, right={literal=1}, operator=>}}}}}}",
				extractor.getAsTree().toString());
