			+ "\n  join fourth t on F4.col1 = t.col2 and F4.col4 = t.col5"
			+ "\n  join fifth f on F4.col1 = f.col2"
			+ "\n where F4.col6 = t.col7 and F4.col1 = t.col2 and F4.col8 > 0"
			+ "\n group by F4.col1, t.col2, t.col3, missing";

