			" s.stvmajr_desc AS concentration_desc, 'T' AS active_ind" +
			" FROM bnr_stvmajr s WHERE s.stvmajr_valid_concentratn_ind = 'Y'" +
			" AND NOT EXISTS ( SELECT 1 FROM cat_concentration c" +
    		" WHERE c.concentration_code = s.stvmajr_code )";

