	@Test
	public void queryOverQueriesMissingUnqualifiedColumnEmitsSpecificFatalAndUnresolved() {
		String sql = "select col3 from (select col1 from tab1) aaa join (select col2 from tab2) bbb on aaa.col1 = bbb.col2";
		final SQLSelectParserParser parser = parse(sql);
		SqlParseEventWalker extractor = runParsertest(sql, parser);

		Snippet snippet = extractor.getSnippet();
		assertFatalDiagnosticAtPosition(snippet,
				"UNQUALIFIED_COLUMN_NOT_FOUND_IN_QUERY_ALIASES",
				"Unqualified column 'col3' at (l:1 c:7) was not found in output interface of any visible query alias [aaa, bbb].",
				"col3",
				1,
				7);
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col3, table_ref=null}}}, from={join={1={table={alias=aaa, query={select={1={column={name=col1, table_ref=null}}}, from={table={alias=null, table=tab1}}}}}, 2={join=join, on={condition={left={column={name=col1, table_ref=aaa}}, right={column={name=col2, table_ref=bbb}}, operator==}}}, 3={table={alias=bbb, query={select={1={column={name=col2, table_ref=null}}}, from={table={alias=null, table=tab2}}}}}}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[col3]", 
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{tab1={col1=[[@5,25:28='col1',<392>,1:25]]}, tab2={col2=[[@13,58:61='col2',<392>,1:58]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{query0={col1=[[@5,25:28='col1',<392>,1:25], [@19,81:83='aaa',<392>,1:81]]}, query1={col2=[[@13,58:61='col2',<392>,1:58], [@23,92:94='bbb',<392>,1:92]]}, query2={col3=[[@1,7:10='col3',<392>,1:7]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong", "{def_query2={query_dictionary={col3=[[@1,7:10='col3',<392>,1:7]]}, def_query1={query_dictionary={col2=[[@13,58:61='col2',<392>,1:58], [@23,92:94='bbb',<392>,1:92]]}, table_dictionary={tab2={col2=[[@13,58:61='col2',<392>,1:58]]}}, interface={col2=[{name=col2, table_ref=tab2}]}}, def_query0={query_dictionary={col1=[[@5,25:28='col1',<392>,1:25], [@19,81:83='aaa',<392>,1:81]]}, table_dictionary={tab1={col1=[[@5,25:28='col1',<392>,1:25]]}}, interface={col1=[{name=col1, table_ref=tab1}]}}, filters=[{name=col1, table_ref=aaa}, {name=col2, table_ref=bbb}], interface={col3=[{name=col3, table_ref=null}]}, table_alias={aaa=query0, bbb=query1}}}",
				extractor.getSymbolTable().toString());

	}

