		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{answer={col1=[[@16,62:64='fff',<392>,3:17]]}, tab2={col2=[[@5,22:25='tab2',<392>,2:16]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{union3={col1=[[@34,141:143='aaa',<392>,4:9], [@46,181:183='aaa',<392>,4:49]]}, query4={col2=[[@40,155:158='col2',<392>,4:23]], col1=[[@36,145:148='col1',<392>,4:13]]}, query0={col2=[[@7,27:30='col2',<392>,2:21], [@25,105:107='eee',<392>,3:60], [@38,151:153='bbb',<392>,4:19], [@50,192:194='bbb',<392>,4:60]]}, query1={col1=[[@18,66:69='col1',<392>,3:21]]}, query2={col2=[[@27,109:112='col2',<392>,3:64]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong",
		 "{def_query4={def_union3={context_list={bbb=query0}, query_dictionary={col1=[[@34,141:143='aaa',<392>,4:9], [@46,181:183='aaa',<392>,4:49]]}, def_query1={context_list={bbb=query0}, query_dictionary={col1=[[@18,66:69='col1',<392>,3:21]]}, table_dictionary={answer={col1=[[@16,62:64='fff',<392>,3:17]]}}, interface={col1=[{name=col1, table_ref=fff}]}, table_alias={bbb=query0, fff=answer}}, interface={col1=query_column}, table_alias={bbb=query0}, def_query2={context_list={bbb=query0, eee=query0}, query_dictionary={col2=[[@27,109:112='col2',<392>,3:64]]}, setop=EXCEPT, interface={col2=[{name=col2, table_ref=eee}]}, table_alias={bbb=query0, eee=query0}}}, context_list={bbb=query0, aaa=union3}, query_dictionary={col2=[[@40,155:158='col2',<392>,4:23]], col1=[[@36,145:148='col1',<392>,4:13]]}, def_query0={query_dictionary={col2=[[@7,27:30='col2',<392>,2:21], [@25,105:107='eee',<392>,3:60], [@38,151:153='bbb',<392>,4:19], [@50,192:194='bbb',<392>,4:60]]}, table_dictionary={tab2={col2=[[@5,22:25='tab2',<392>,2:16]]}}, interface={col2=[{name=col2, table_ref=tab2}]}}, filters=[{name=col1, table_ref=aaa}, {name=col2, table_ref=bbb}], interface={col2=[{name=col2, table_ref=bbb}], col1=[{name=col1, table_ref=aaa}]}, table_alias={aaa=union3, bbb=query0}}}",
				extractor.getSymbolTable().toString());
