				+ "\n ccc AS ((VALUES (1001, 2001, 3001), (1002, 2002, 3002)))"
				+ "\n SELECT ppp.a1, qqq.b2"
				+ "\n FROM aaa AS ppp"
				+ "\n JOIN bbb AS qqq ON ppp.a1 = qqq.b1"
				+ "\n JOIN ccc AS rrr ON qqq.b1 = $1";

