		Assert.assertEquals("Substitution List is wrong", "{}",
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{tab3={c3=[[@84,274:276='nnn',<392>,6:36]], c1=[[@76,258:260='nnn',<392>,6:20], [@105,352:354='nnn',<392>,6:114]], c2=[[@80,266:268='nnn',<392>,6:28]]}, hhh={a1=[[@10,48:50='hhh',<392>,2:42]], a2=[[@16,62:64='hhh',<392>,2:56]], a3=[[@22,76:78='hhh',<392>,2:70]]}, tab2={b2=[[@41,142:144='lll',<392>,5:28]], b3=[[@45,150:152='lll',<392>,5:36], [@66,228:230='lll',<392>,5:114]], b1=[[@37,134:136='lll',<392>,5:20]]}}",
				extractor.getTableColumnDictionaryMap().toString());
