		Assert.assertEquals("Substitution List is wrong", "{}", 
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{tab3={col3=[[@39,184:187='tab3',<392>,6:25]]}, tab4={col4=[[@64,368:371='tab4',<392>,10:18]]}, tab1={col1=[[@5,22:25='tab1',<392>,2:16]]}, tab2={col2=[[@22,108:111='tab2',<392>,4:31]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{query4={missing_from_derived=[[@58,315:334='missing_from_derived',<392>,8:43]], missing_from_shadow=[[@52,251:269='missing_from_shadow',<392>,7:33]], *=[[@80,443:443='*',<291>,12:10]]}, query5={*=[[@80,443:443='*',<291>,12:10]]}, query6={*=[[@85,471:471='*',<291>,15:8]]}, query0={inherited_col=[[@9,35:47='inherited_col',<392>,2:29]], *=[[@80,443:443='*',<291>,12:10]]}, query1={middle_col=[[@26,121:130='middle_col',<392>,4:44]], *=[[@80,443:443='*',<291>,12:10]]}, query2={local_col=[[@43,197:205='local_col',<392>,6:38]], *=[[@80,443:443='*',<291>,12:10]]}, query3={other_col=[[@68,381:389='other_col',<392>,10:31]], *=[[@80,443:443='*',<291>,12:10]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
