	@Test
	public void normalMultiTableTest() {
			
		final String query = " select source.col1, target.col2 from (select col1 from tab1) as source join (select col2 from tab2) as target";
		final SQLSelectParserParser parser = parse(query);
		SqlParseEventWalker extractor = runParsertest(query, parser);
		assertNoWalkerDiagnostics(extractor);
				
		Assert.assertEquals("Interface is wrong", "[col2, col1]", 
					extractor.getInterface().toString());
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=source}}, 2={column={name=col2, table_ref=target}}}, from={join={1={table={alias=source, query={select={1={column={name=col1, table_ref=null}}}, from={table={alias=null, table=tab1}}}}}, 2={join=join}, 3={table={alias=target, query={select={1={column={name=col2, table_ref=null}}}, from={table={alias=null, table=tab2}}}}}}}}}",
					extractor.getAsTree().toString());
		Assert.assertEquals("Substitution List is wrong", "{}", 
					extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{tab1={col1=[[@11,46:49='col1',<392>,1:46]]}, tab2={col2=[[@20,85:88='col2',<392>,1:85]]}}",
					extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{query0={col1=[[@11,46:49='col1',<392>,1:46], [@1,8:13='source',<392>,1:8]]}, query1={col2=[[@20,85:88='col2',<392>,1:85], [@5,21:26='target',<392>,1:21]]}, query2={col2=[[@7,28:31='col2',<392>,1:28]], col1=[[@3,15:18='col1',<392>,1:15]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong", "{def_query2={query_dictionary={col2=[[@7,28:31='col2',<392>,1:28]], col1=[[@3,15:18='col1',<392>,1:15]]}, def_query1={query_dictionary={col2=[[@20,85:88='col2',<392>,1:85], [@5,21:26='target',<392>,1:21]]}, table_dictionary={tab2={col2=[[@20,85:88='col2',<392>,1:85]]}}, interface={col2=[{name=col2, table_ref=tab2}]}}, def_query0={query_dictionary={col1=[[@11,46:49='col1',<392>,1:46], [@1,8:13='source',<392>,1:8]]}, table_dictionary={tab1={col1=[[@11,46:49='col1',<392>,1:46]]}}, interface={col1=[{name=col1, table_ref=tab1}]}}, interface={col2=[{name=col2, table_ref=target}], col1=[{name=col1, table_ref=source}]}, table_alias={source=query0, target=query1}}}",
					extractor.getSymbolTable().toString());
	}


