	@Test
	public void unaliasedValuesPositionalAllOuterClausesV13Test() {
		// plain unaliased VALUES (positional $1/$2/$3)
		final String query =
			"SELECT col1, col2, SUM(col3) AS total\n" +
			"FROM (VALUES (1, 2, 3), (4, 5, 6))\n" +
			"JOIN (SELECT col2 AS match_col FROM tab2) ON col1 = match_col\n" +
			"WHERE col3 > 0\n" +
			"  AND EXISTS (SELECT ex1 FROM (select ex1 from tab3) x WHERE x.ex1 = col1)\n" +
			"GROUP BY col1, col2\n" +
			"HAVING SUM(col3) > 10\n" +
			"QUALIFY ROW_NUMBER() OVER (PARTITION BY col1 ORDER BY col2) = 1\n" +
			"ORDER BY col1, col2";
		final SQLSelectParserParser parser = parse(query);
		ParserRunResult runResult = runSQLParsertestAllowErrors(query, parser);
		SqlParseEventWalker extractor = runResult.getExtractor();
		Assert.assertTrue("Expected self-alias registration for inner source",
				extractor.getSymbolTable().toString().contains("values0=values0"));
		Assert.assertEquals("AST is wrong", "{SQL={select={1={column={name=col1, table_ref=null}}, 2={column={name=col2, table_ref=null}}, 3={function={function_name=SUM, qualifier=null, parameters={column={name=col3, table_ref=null}}}, alias=total}}, having={condition={left={function={function_name=SUM, qualifier=null, parameters={column={name=col3, table_ref=null}}}}, right={literal=10}, operator=>}}, orderby={1={null_order=null, predicand={column={name=col1, table_ref=null}}, sort_order=ASC}, 2={null_order=null, predicand={column={name=col2, table_ref=null}}, sort_order=ASC}}, from={join={1={values={matrix={1={row={1={literal=1}, 2={literal=2}, 3={literal=3}}}, 2={row={1={literal=4}, 2={literal=5}, 3={literal=6}}}}}}, 2={join=JOIN, on={condition={left={column={name=col1, table_ref=null}}, right={column={name=match_col, table_ref=null}}, operator==}}}, 3={select={1={column={name=col2, table_ref=null}, alias=match_col}}, from={table={alias=null, table=tab2}}}}}, where={and={1={condition={left={column={name=col3, table_ref=null}}, right={literal=0}, operator=>}}, 2={exists={select={1={column={name=ex1, table_ref=null}}}, from={table={alias=x, query={select={1={column={name=ex1, table_ref=null}}}, from={table={alias=null, table=tab3}}}}}, where={condition={left={column={name=ex1, table_ref=x}}, right={column={name=col1, table_ref=null}}, operator==}}, operator=EXISTS}}}}, groupby={1={column={name=col1, table_ref=null}}, 2={column={name=col2, table_ref=null}}}, qualify={condition={left={window_function={over={partition_by={1={column={name=col1, table_ref=null}}}, orderby={1={null_order=null, predicand={column={name=col2, table_ref=null}}, sort_order=ASC}}}, function={function_name=ROW_NUMBER, parameters=null}}}, right={literal=1}, operator==}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[total, col2, col1]",
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}",
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{tab3={ex1=[[@55,188:190='ex1',<392>,5:38]]}, tab2={col2=[[@33,86:89='col2',<392>,3:13]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{values0={$1=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]], $2=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]], $3=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]]}, query5={total=[[@10,32:36='total',<392>,1:32]], col2=[[@3,13:16='col2',<392>,1:13]], col1=[[@1,7:10='col1',<392>,1:7]]}, query1={match_col=[[@35,94:102='match_col',<392>,3:21], [@42,125:133='match_col',<392>,3:52]]}, query2={ex1=[[@55,188:190='ex1',<392>,5:38], [@61,211:211='x',<392>,5:61], [@51,171:173='ex1',<392>,5:21]]}, query3={ex1=[[@51,171:173='ex1',<392>,5:21]]}}",
				extractor.getQueryColumnDictionaryMap().toString());

		Assert.assertEquals("Symbol Table is wrong",
		 "{def_query5={window_ordered_by=[{name=col2, table_ref=null}], def_values0={query_dictionary={$1=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]], $2=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]], $3=[[@14,51:51='(',<287>,2:13], [@22,62:62='(',<287>,2:24]]}, interface={$1=[], $2=[], $3=[]}}, grouped_by=[{name=col1, table_ref=null}, {name=col2, table_ref=null}], window_partition_by=[{name=col1, table_ref=null}], def_query1={query_dictionary={match_col=[[@35,94:102='match_col',<392>,3:21], [@42,125:133='match_col',<392>,3:52]]}, table_dictionary={tab2={col2=[[@33,86:89='col2',<392>,3:13]]}}, interface={match_col=[{name=col2, table_ref=tab2}]}}, ordered_by=[{name=col1, table_ref=null}, {name=col2, table_ref=null}], filters=[{name=col1, table_ref=null}, {name=match_col, table_ref=query1}, {name=col3, table_ref=null}, {name=col2, table_ref=null}], interface={total=[{name=col3, table_ref=null}], col2=[{name=col2, table_ref=null}], col1=[{name=col1, table_ref=null}]}, def_query3={query_dictionary={ex1=[[@51,171:173='ex1',<392>,5:21]]}, filters=[{name=ex1, table_ref=x}, {name=col1, table_ref=null}], interface={ex1=[{name=ex1, table_ref=query2}]}, table_alias={x=query2}, def_query2={query_dictionary={ex1=[[@55,188:190='ex1',<392>,5:38], [@61,211:211='x',<392>,5:61], [@51,171:173='ex1',<392>,5:21]]}, table_dictionary={tab3={ex1=[[@55,188:190='ex1',<392>,5:38]]}}, interface={ex1=[{name=ex1, table_ref=tab3}]}}}, query_dictionary={total=[[@10,32:36='total',<392>,1:32]], col2=[[@3,13:16='col2',<392>,1:13]], col1=[[@1,7:10='col1',<392>,1:7]]}, dependent_queries={exists4={query=query3, type=filters}}, table_alias={values0=values0, query1=query1}}}",
					extractor.getSymbolTable().toString());

		Snippet snippet = extractor.getSnippet();
		assertFatalDiagnosticAtPosition(
				snippet,
				"UNQUALIFIED_COLUMN_NOT_FOUND_IN_QUERY_ALIASES",
				"Unqualified column 'col1' at (l:1 c:7) was not found in output interface of any visible query alias [values0, query1].",
				"col1",
				1,
				7);
		assertFatalDiagnosticAtPosition(
				snippet,
				"UNQUALIFIED_COLUMN_NOT_FOUND_IN_QUERY_ALIASES",
				"Unqualified column 'col2' at (l:1 c:13) was not found in output interface of any visible query alias [values0, query1].",
				"col2",
				1,
				13);
		assertFatalDiagnosticAtPosition(
				snippet,
				"UNQUALIFIED_COLUMN_NOT_FOUND_IN_QUERY_ALIASES",
				"Unqualified column 'col3' at (l:1 c:23) was not found in output interface of any visible query alias [values0, query1].",
				"col3",
				1,
				23);
	}

