	// --- Three-level UNION / INTERSECT / EXCEPT nesting (6 permutations x happy + mismatch) ---

	@Test
	public void threeLevelSetOpNestUnionIntersectExceptHappyPathTest() {
		// Three-level nesting: left=UNION, mid=INTERSECT, right=EXCEPT; matching column counts
		final String query = "("
				+ "(SELECT first FROM third UNION SELECT third FROM fifth)"
				+ " INTERSECT "
				+ "(SELECT fourth FROM sixth EXCEPT SELECT seventh FROM eighth)"
				+ ")";
		final SQLSelectParserParser parser = parse(query);
		SqlParseEventWalker extractor = runParsertest(query, parser);
		assertNoWalkerDiagnostics(extractor);
		Assert.assertTrue("Expected setop=UNION", extractor.getSymbolTable().toString().contains("setop=UNION"));
		Assert.assertTrue("Expected setop=INTERSECTION", extractor.getSymbolTable().toString().contains("setop=INTERSECTION"));
		Assert.assertTrue("Expected setop=EXCEPT", extractor.getSymbolTable().toString().contains("setop=EXCEPT"));
		Assert.assertEquals("AST is wrong", "{SQL={intersect={1={union={1={select={1={column={name=first, table_ref=null}}}, from={table={alias=null, table=third}}}, 2={union={qualifier=null, operator=UNION}}, 3={select={1={column={name=third, table_ref=null}}}, from={table={alias=null, table=fifth}}}}}, 2={intersect={qualifier=null, operator=INTERSECT}}, 3={union={1={select={1={column={name=fourth, table_ref=null}}}, from={table={alias=null, table=sixth}}}, 2={union={qualifier=null, operator=EXCEPT}}, 3={select={1={column={name=seventh, table_ref=null}}}, from={table={alias=null, table=eighth}}}}}}}}",
				extractor.getAsTree().toString());
		Assert.assertEquals("Interface is wrong", "[first]",
				extractor.getInterface().toString());
		Assert.assertEquals("Substitution List is wrong", "{}",
				extractor.getSubstitutionsMap().toString());
		Assert.assertEquals("Table Dictionary is wrong", "{sixth={fourth=[[@15,75:80='fourth',<392>,1:75]]}, third={first=[[@3,9:13='first',<88>,1:9]]}, eighth={seventh=[[@20,107:113='seventh',<392>,1:107]]}, fifth={third=[[@8,39:43='third',<392>,1:39]]}}",
				extractor.getTableColumnDictionaryMap().toString());
		Assert.assertEquals("Query Column Dictionary is wrong", "{query4={seventh=[[@20,107:113='seventh',<392>,1:107]]}, query0={first=[[@3,9:13='first',<88>,1:9]]}, query1={third=[[@8,39:43='third',<392>,1:39]]}, query3={fourth=[[@15,75:80='fourth',<392>,1:75]]}}",
				extractor.getQueryColumnDictionaryMap().toString());
		Assert.assertEquals("Symbol Table is wrong",
		 "{def_intersect6={def_union2={def_query1={query_dictionary={third=[[@8,39:43='third',<392>,1:39]]}, table_dictionary={fifth={third=[[@8,39:43='third',<392>,1:39]]}}, setop=UNION, interface={third=[{name=third, table_ref=fifth}]}}, def_query0={query_dictionary={first=[[@3,9:13='first',<88>,1:9]]}, table_dictionary={third={first=[[@3,9:13='first',<88>,1:9]]}}, interface={first=[{name=first, table_ref=third}]}}, interface={first=query_column}}, interface={first=query_column}, def_union5={setop=INTERSECTION, interface={fourth=query_column}, def_query4={query_dictionary={seventh=[[@20,107:113='seventh',<392>,1:107]]}, table_dictionary={eighth={seventh=[[@20,107:113='seventh',<392>,1:107]]}}, setop=EXCEPT, interface={seventh=[{name=seventh, table_ref=eighth}]}}, def_query3={query_dictionary={fourth=[[@15,75:80='fourth',<392>,1:75]]}, table_dictionary={sixth={fourth=[[@15,75:80='fourth',<392>,1:75]]}}, interface={fourth=[{name=fourth, table_ref=sixth}]}}}}}",
				extractor.getSymbolTable().toString());
	}

